"""Independent reference model: LPM + image validator + image lookup (from PROTOCOL.md)."""
import json

M64 = (1 << 64) - 1
BMP_NULL = 4194303

def norm(addr, ln):
    v = int(addr, 16)
    if ln == 0:
        return 0
    return (v >> (128 - ln)) << (128 - ln)

def split(v):
    return (v >> 64) & M64, v & M64

class Fib:
    def __init__(self):
        self.p = {}   # (len, value) -> hop
    def put(self, addr, ln, hop):
        self.p[(ln, norm(addr, ln))] = hop
    def lpm(self, addr):
        v = int(addr, 16)
        for ln in range(128, -1, -1):
            key = (ln, norm(addr, ln))
            if key in self.p:
                return self.p[key]
        return None

# ------------------------------------------------------------------ image ----

def owner(origin):
    return {0: 16, 16: 64, 64: 128}[origin]

def bits128(v, d, n):
    if n <= 0:
        return 0
    return (v >> (128 - d - n)) & ((1 << n) - 1)

def top(v, ln):
    if ln <= 0:
        return 0
    return (v >> (128 - ln)) << (128 - ln)

def w2i(word):
    assert len(word) == 64, "word width"
    return int(word, 16)

def rec_bits(w, off, n):
    return (w >> off) & ((1 << n) - 1)

class Bad(Exception):
    pass

class Image:
    """Validated image; raises Bad on any violation."""

    def __init__(self, d):
        self.d = d
        self.nodes = {}
        self.used = [dict() for _ in range(11)]      # stage -> cell -> 'full'/'half'
        self.slot = [dict() for _ in range(11)]      # stage -> cell -> node idx
        self.ni_used = set()
        self.pat_used = set()
        cells = d['cells']
        banks = d['banks']
        if len(cells) != 11 or any(not isinstance(x, int) or x < 0 or x > 131072 for x in cells):
            raise Bad('cells')
        if len(banks) != 11:
            raise Bad('banks')
        total = 0
        for s in range(11):
            if len(banks[s]) != (cells[s] + 1) // 2:
                raise Bad('bank rows')
            total += cells[s]
        if total > 131072:
            raise Bad('total cells')
        if len(d['bitmaps']) > 8193 or len(d['nexthops']) > 8192:
            raise Bad('side ram')
        for i in range(1, len(d['bitmaps'])):
            if d['bitmaps'][i - 1] >= d['bitmaps'][i]:
                raise Bad('bitmap order')
        if d['root'] is not None:
            self.root = self.decode(d['root'][0], d['root'][1], 0, 0, 0, 0, False)
        else:
            self.root = None
        self.f16 = []
        for e in d['front16']:
            key = int(e[0], 16)
            idx = self.decode(e[1][0], e[1][1], 16, 16, key << 48, 0, False)
            self.f16.append((key, idx))
        self.f64 = []
        for e in d['front64']:
            key = int(e[0], 16)
            idx = self.decode(e[1][0], e[1][1], 64, 64, key, 0, False)
            self.f64.append((key, idx))
        for k in range(1, len(self.f16)):
            if self.f16[k - 1][0] >= self.f16[k][0]:
                raise Bad('front16 order')
        for k in range(1, len(self.f64)):
            if self.f64[k - 1][0] >= self.f64[k][0]:
                raise Bad('front64 order')
        # dense coverage
        for s in range(11):
            if len(self.used[s]) != cells[s]:
                raise Bad('coverage stage %d' % s)
            for c in range(cells[s]):
                if c not in self.used[s]:
                    raise Bad('hole stage %d cell %d' % (s, c))
            if cells[s] & 1:
                row = banks[s][cells[s] >> 1]
                if row >> 128:
                    raise Bad('padding row')
        for i in range(len(d['bitmaps'])):
            if i not in self.pat_used:
                raise Bad('unused pattern')
        for i in range(len(d['nexthops'])):
            if i not in self.ni_used:
                raise Bad('unused ni')
        self.prefixes = {}
        self.collect()
        if len(self.prefixes) > 8192:
            raise Bad('fib size')
        self.check_bmps()

    def decode(self, stage, cell, origin, depth, reghi, reglo, bulk):
        if stage < 0 or stage > 10:
            raise Bad('stage')
        if cell >= self.d['cells'][stage]:
            raise Bad('cell range')
        if depth > owner(origin):
            raise Bad('depth beyond owner')
        w = self.d['banks'][stage][cell >> 1]
        off = (cell & 1) * 128
        typ = rec_bits(w, off, 3)
        if typ < 1 or typ > 5:
            raise Bad('type')
        span = 2 if typ in (2, 3, 5) else 1
        if span == 2 and cell & 1:
            raise Bad('odd full slot')
        if bulk and cell & 1:
            raise Bad('odd bulk slot')
        if cell + span > self.d['cells'][stage]:
            raise Bad('beyond cells')
        if cell in self.used[stage] or (span == 2 and cell + 1 in self.used[stage]):
            raise Bad('overlap')
        if cell in self.slot[stage]:
            raise Bad('alias')
        rec = (w >> off) & ((1 << (span * 128)) - 1)
        idx = len(self.nodes)
        node = {'type': typ, 'origin': origin, 'depth': depth, 'stage': stage,
                'reghi': reghi, 'reglo': reglo, 'bmp': rec_bits(rec, 3, 22),
                'children': [], 'inlines': []}
        self.used[stage][cell] = span
        self.slot[stage][cell] = idx
        if span == 2:
            self.used[stage][cell + 1] = 2
        self.nodes.append(node)
        mx = owner(origin)
        lmin = max(1 if origin else 0, depth - origin)
        kids = []
        if typ in (4, 5):
            base = [25, 119]
            for k in range(1 if typ == 4 else 2):
                frag = rec_bits(rec, base[k], 64)
                l = rec_bits(rec, base[k] + 64, 8)
                hop = rec_bits(rec, base[k] + 72, 22)
                if hop >= BMP_NULL:
                    raise Bad('inline hop')
                if l < lmin or l > mx - origin:
                    raise Bad('inline length')
                if l < 64 and frag & ((1 << (64 - l)) - 1):
                    raise Bad('host bits')
                if origin == 0:
                    phi, plo = frag, 0
                elif origin == 16:
                    phi, plo = reghi | (frag >> 16), 0
                else:
                    phi, plo = reghi, frag
                if top(phi << 64 | plo, depth) != (reghi << 64 | reglo):
                    raise Bad('foreign inline prefix')
                node['inlines'].append((l, hop, phi << 64 | plo))
            if typ == 5 and node['inlines'][0][2:] == node['inlines'][1][2:]:
                raise Bad('identical inline pair')
            if rec_bits(rec, 119 if typ == 4 else 213, 9 if typ == 4 else 43):
                raise Bad('reserved')
        else:
            bid = rec_bits(rec, 25, 16)
            if bid >= len(self.d['bitmaps']):
                raise Bad('bitmap id')
            pat = self.d['bitmaps'][bid]
            self.pat_used.add(bid)
            node['pattern'] = pat
            node['ni_base'] = rec_bits(rec, 41, 22)
            node['ni_count'] = bin(pat).count('1')
            if pat & 1:
                raise Bad('bit0')
            maxl = min(5, mx - depth)
            if node['ni_count'] == 0:
                if node['ni_base'] != 0:
                    raise Bad('empty base')
            else:
                if node['ni_base'] + node['ni_count'] > len(self.d['nexthops']):
                    raise Bad('ni range')
                for k in range(node['ni_count']):
                    if node['ni_base'] + k in self.ni_used:
                        raise Bad('ni overlap')
                    self.ni_used.add(node['ni_base'] + k)
            for b in range(1, 64):
                if pat >> b & 1:
                    if 63 - b.bit_length() + 1 > maxl:
                        raise Bad('ni level')
            if typ == 1:
                if rec_bits(rec, 127, 1):
                    raise Bad('reserved')
                seen = False
                last = -1
                for k in range(2):
                    raw = rec_bits(rec, 63 + 32 * k, 32)
                    if raw == 15 << 6:
                        seen = True
                        continue
                    if seen:
                        raise Bad('child order')
                    key = raw & 0x3F
                    cst = (raw >> 6) & 0xF
                    ccell = (raw >> 10) & 0x3FFFFF
                    if cst > 10 or cst >= stage:
                        raise Bad('child stage')
                    if key <= last:
                        raise Bad('child key order')
                    last = key
                    if depth + 6 > mx:
                        raise Bad('child beyond owner')
                    chi = reghi
                    clo = reglo
                    if depth + 6 <= 64:
                        chi |= key << (64 - depth - 6)
                    else:
                        clo |= key << (128 - depth - 6)
                    kids.append(self.decode(cst, ccell, origin, depth + 6, chi, clo, False))
                    node['children'].append((key, cst, ccell))
            elif typ == 2:
                if rec_bits(rec, 255, 1):
                    raise Bad('reserved')
                seen = False
                last = -1
                for k in range(6):
                    raw = rec_bits(rec, 63 + 32 * k, 32)
                    if raw == 15 << 6:
                        seen = True
                        continue
                    if seen:
                        raise Bad('child order')
                    key = raw & 0x3F
                    cst = (raw >> 6) & 0xF
                    ccell = (raw >> 10) & 0x3FFFFF
                    if cst > 10 or cst >= stage:
                        raise Bad('child stage')
                    if key <= last:
                        raise Bad('child key order')
                    last = key
                    if depth + 6 > mx:
                        raise Bad('child beyond owner')
                    chi = reghi
                    clo = reglo
                    if depth + 6 <= 64:
                        chi |= key << (64 - depth - 6)
                    else:
                        clo |= key << (128 - depth - 6)
                    kids.append(self.decode(cst, ccell, origin, depth + 6, chi, clo, False))
                    node['children'].append((key, cst, ccell))
                if len(node['children']) < 3:
                    raise Bad('type2 arity')
            else:
                if rec_bits(rec, 249, 7):
                    raise Bad('reserved')
                node['bulk_bitmap'] = rec_bits(rec, 63, 64)
                node['bulk_base'] = rec_bits(rec, 127, 22)
                bstage = rec_bits(rec, 149, 4)
                if bstage > 10 or bstage >= stage:
                    raise Bad('bulk stage')
                if node['bulk_base'] & 1:
                    raise Bad('bulk base odd')
                b = bin(node['bulk_bitmap']).count('1')
                seen = False
                last = -1
                for k in range(3):
                    raw = rec_bits(rec, 153 + 32 * k, 32)
                    if raw == 15 << 6:
                        seen = True
                        continue
                    if seen:
                        raise Bad('direct order')
                    key = raw & 0x3F
                    cst = (raw >> 6) & 0xF
                    ccell = (raw >> 10) & 0x3FFFFF
                    if cst > 10 or cst >= stage:
                        raise Bad('direct stage')
                    if key <= last:
                        raise Bad('direct key order')
                    if node['bulk_bitmap'] >> key & 1:
                        raise Bad('direct/bulk clash')
                    last = key
                    node['children'].append((key, cst, ccell))
                if not (7 <= b + len(node['children']) <= 64):
                    raise Bad('type3 arity')
                if node['bulk_base'] + 2 * b > self.d['cells'][bstage]:
                    raise Bad('bulk range')
                if depth + 6 > mx:
                    raise Bad('child beyond owner')
                rank = 0
                for v in range(64):
                    if not (node['bulk_bitmap'] >> v & 1):
                        continue
                    chi = reghi
                    clo = reglo
                    if depth + 6 <= 64:
                        chi |= v << (64 - depth - 6)
                    else:
                        clo |= v << (128 - depth - 6)
                    kids.append(self.decode(bstage, node['bulk_base'] + 2 * rank, origin,
                                            depth + 6, chi, clo, True))
                    rank += 1
                for (key, cst, ccell) in node['children']:
                    chi = reghi
                    clo = reglo
                    if depth + 6 <= 64:
                        chi |= key << (64 - depth - 6)
                    else:
                        clo |= key << (128 - depth - 6)
                    kids.append(self.decode(cst, ccell, origin, depth + 6, chi, clo, False))
        own = len(node['inlines'])
        if typ <= 3:
            own += node['ni_count']
        for k in kids:
            own += self.nodes[k]['owned']
        node['owned'] = own
        if own <= 0:
            raise Bad('empty subtree')
        if own == 1 and typ != 4:
            raise Bad('own1')
        if own == 2 and typ != 5:
            raise Bad('own2')
        if own >= 3 and typ > 3:
            raise Bad('own3')
        return idx

    def collect(self):
        for node in self.nodes:
            for (l, hop, pv) in node['inlines']:
                key = (node['origin'] + l, pv)
                if key in self.prefixes:
                    raise Bad('duplicate prefix')
                self.prefixes[key] = hop
            if node['type'] <= 3:
                pat = node['pattern']
                p = pat
                while p:
                    b = p & -p
                    p ^= b
                    pos = b.bit_length() - 1
                    l = 63 - pos.bit_length() + 1
                    v = pos - (1 << l)
                    off = bin(pat & ((1 << pos) - 1)).count('1')
                    hop = self.d['nexthops'][node['ni_base'] + off]
                    val = (node['reghi'] << 64 | node['reglo']) | (v << (128 - node['depth'] - l))
                    key = (node['depth'] + l, val)
                    if key in self.prefixes:
                        raise Bad('duplicate prefix')
                    self.prefixes[key] = hop

    def check_bmps(self):
        for node in self.nodes:
            reg = node['reghi'] << 64 | node['reglo']
            want = None
            for ln in range(node['depth'], -1, -1):
                key = (ln, top(reg, ln))
                if key in self.prefixes:
                    want = self.prefixes[key]
                    break
            if want != (None if node['bmp'] == BMP_NULL else node['bmp']):
                raise Bad('bmp mismatch')

    def lookup(self, addr):
        v = int(addr, 16)
        hi, lo = v >> 64, v & M64
        for (key, idx) in self.f64:
            if key == hi:
                return self.walk(idx, lo)
        for (key, idx) in self.f16:
            if key == hi >> 48:
                return self.walk(idx, (hi << 16) & M64)
        if self.root is not None:
            return self.walk(self.root, hi)
        return None

    def walk(self, idx, cursor):
        node = self.nodes[idx]
        if node['type'] in (4, 5):
            best = (-1, None)
            for (l, hop, pv) in node['inlines']:
                m = True if l == 0 else ((cursor >> (64 - l)) == (pv >> (128 - l)))
                if m and l > best[0]:
                    best = (l, hop)
            if best[0] >= 0:
                return best[1]
            return None if node['bmp'] == BMP_NULL else node['bmp']
        t = (node['depth'] - node['origin']) // 6
        chunk = (cursor >> (58 - 6 * t)) & 0x3F
        for (key, cst, ccell) in node['children']:
            if key == chunk:
                return self.walk(self.slot[cst][ccell], cursor)
        if node['type'] == 3 and node['bulk_bitmap'] >> chunk & 1:
            rank = bin(node['bulk_bitmap'] & ((1 << chunk) - 1)).count('1')
            return self.walk(self.slot[node['bulk_stage']][node['bulk_base'] + 2 * rank], cursor)
        pat = node['pattern']
        for l in range(5, -1, -1):
            pos = (1 << l) + (chunk >> (6 - l))
            if pat >> pos & 1:
                off = bin(pat & ((1 << pos) - 1)).count('1')
                return self.d['nexthops'][node['ni_base'] + off]
        return None if node['bmp'] == BMP_NULL else node['bmp']
